  "sl": {"saved":"تذكُّر ما في خزانتك خصم {a} من هذه التسوقة. على مدى شهر من الطبخ يعني ذلك نحو {b} لم تنفقها مرتين.","measured":"معظم هذه السلة مقيس فعلياً — يزور الباحثون أسواق {c} شهرياً. تغطية جيدة بشكل غير معتاد.","modelled":"بصراحة معك: في {c} معظم هذه السلة مُقدَّر لا مقيس. لا توجد سلسلة متاجر تنشر أسعارها بهذا الحجم. اعتبرها تقديراً جيداً، لا فاتورة.","listEnglish":"أسماء المكوّنات كما على العبوة","listWhy":"رفوف المتاجر مكتوبة باللغة المحلية. أعرض لك الاسم الذي ستقرأه فعلاً على العبوة."},
  "q": {"training":{"q":"اخترت الأطباق عالية البروتين {k} مرة من أصل {n}.","why":"إن كان لذلك سبب فبإمكاني أن أصوّب بدقة بدل التخمين. هل تتمرّن؟","o":["أرفع أثقالاً","أجري أو أركب الدراجة","لا، أحبها فقط"]},"calorieGoal":{"q":"{k} من آخر {n} أطباق كانت أقل من ٥٠٠ سعرة.","why":"هذا نمط لا صدفة. ما الغرض منه؟","o":["إنقاص الوزن","تحسين التركيب الجسدي","هكذا جاءت الأمور"]},"cuisine":{"q":"{k} من آخر {n} مرات طبخت مطبخاً {c}.","why":"هل أميل إلى هذا الاتجاه حين لا يكون لديّ ما هو أفضل، أم أواصل التنويع؟","o":["مِل إلى {c}","واصل التنويع"]},"push":{"q":"لا شيء طبخته خلال شهر تجاوز درجة صعوبة اثنين.","why":"يمكنني إبقاء الأمور سهلة، أو أن أدسّ طبقاً أصعب كل أسبوع.","o":["ادفعني قليلاً","أبقِها سهلة"]},"budget":{"q":"متوسطك {a} للحصة مقابل سلة بـ {b}.","why":"هذا أضيق مما يبدو. أرفع الميزانية الافتراضية كي أتوقف عن إخفاء الأطباق عنك؟","o":["ارفعها","اتركها"]},"empty":"لا شيء بعد. لا أحتفظ بشيء إلا حين تجيب عن سؤال بصوتك — لا أستنتج هدفاً من طبخك ثم أتصرف على أساسه بصمت.","forget":"انسَ هذا","noted":"سُجّل"},
  "L": {"training:strength":["ترفع الأثقال","تُرتَّب الأطباق حسب البروتين أولاً، ولن أقترح في يوم تمرين أي طبق أقل من ٣٠ غراماً للحصة."],"training:endurance":["تجري أو تركب الدراجة","أبقي الكربوهيدرات مرتفعة بدل خفضها، وتوقّفت عن إخفاء الأطباق الأعلى سعرات عنك."],"calorieGoal:cut":["أنت في مرحلة تخفيف","السعرات في مقدمة كل بطاقة، وأي طبق يتجاوز ٦٠٠ سعرة للحصة يحصل على تنبيه لا على إخفاء."],"calorieGoal:recomp":["أنت تعيد تشكيل جسمك","أرتّب حسب البروتين لكل سعرة بدل السعرات وحدها، وهذا يغيّر الترتيب كثيراً."],"push:yes":["تريد أن تُدفَع قليلاً","طبق واحد أسبوعياً صار الآن درجة فوق قائمتك، وأخبرك أيّها هو."],"budget:up":["رُفعت الميزانية","كنت تنفق باستمرار فوق الرقم الذي حدّدته، فتوقّفت عن التصفية بالرقم القديم."],"goal":["هدفك: {v}","أخبرتني بهذا عند الدخول. هو يعيد ترتيب ما أعرضه أولاً فقط — كل شيء ما زال موجوداً، ويمكنك حذف هذا السطر."],"cuisine":["ميل نحو {v}","حين لا يكون لديّ ما هو أفضل أرفع أطباق {v} في القائمة. لا يخفي شيئاً ويتوقف لحظة حذفك له."]},
